using StateLandGovernance.GovernanceIntelligence.Application.DTOs;
using StateLandGovernance.GovernanceIntelligence.Application.OfficerFlows;
using StateLandGovernance.GovernanceIntelligence.Application.RegulatoryReports;
namespace StateLandGovernance.UnitTests.GovernanceIntelligence;
public sealed class C4ScreeningResolutionTests {
 static ComplianceFindingDto[] Findings()=>Enumerable.Range(0,24).Select(i=>new ComplianceFindingDto("RULE-"+i,"arbitrary","Any","Applicable",i<14?"Compliant":i<21?"InsufficientInformation":"RequiresHumanReview","Review",i>=14,i>=14,"Original immutable input","A later institutional approval is required","Unverified","MissingInputs","Authority","Original document","Section","Original recommendation")).ToArray();
 static RegulatoryFollowupEvent Close(ComplianceFindingDto f,Guid eval)=>new(Guid.NewGuid(),eval,f.RuleCode,f.RuleVersion,Guid.NewGuid(),DateTimeOffset.UtcNow,"FindingVerifiedClosed",null,null,"",[],"Recorded",1,null,new string('a',64));
 [Fact] public void FourteenCompliantTenClosuresResolveAllTwentyFourOnlyForC4(){var id=Guid.NewGuid();var f=Findings();var before=System.Text.Json.JsonSerializer.Serialize(f);var events=f.Skip(14).Select(x=>Close(x,id)).ToArray();Assert.Empty(RegulatoryProgression.Holds(f,events,id));Assert.Equal(before,System.Text.Json.JsonSerializer.Serialize(f));Assert.All(events,x=>Assert.Equal("FindingVerifiedClosed",x.Operation));}
 [Fact] public void NineClosuresLeaveExactlyOneOutstandingAndFinalClosureClearsIt(){var id=Guid.NewGuid();var f=Findings();var history=f.Skip(14).Take(9).Select(x=>Close(x,id)).ToArray();Assert.Equal(["RULE-23"],RegulatoryProgression.Holds(f,history,id).Select(x=>x.Split(':')[0]));Assert.Empty(RegulatoryProgression.Holds(f,[..history,Close(f[23],id)],id));}
 [Fact] public void PreviousEvaluationAndWrongRuleVersionCannotResolveCurrentFindings(){var id=Guid.NewGuid();var f=Findings();Assert.Equal(10,RegulatoryProgression.Holds(f,f.Skip(14).Select(x=>Close(x,Guid.NewGuid())).ToArray(),id).Length);Assert.Equal(10,RegulatoryProgression.Holds(f,f.Skip(14).Select(x=>Close(x,id) with{RuleVersion="different"}).ToArray(),id).Length);}
 [Fact] public void LatestValidHumanReviewCountsAsAddressedRegardlessOfOutstandingConcern(){var id=Guid.NewGuid();var f=Findings()[23];var review=Close(f,id) with{Operation="HumanReviewRecorded",ReviewOutcome="NoAdditionalConcern",Remarks="A reasoned review with sufficient recorded detail."};Assert.Empty(RegulatoryProgression.Holds([f],[review],id));Assert.Empty(RegulatoryProgression.Holds([f],[review,review with{Revision=2,ReviewOutcome="AdditionalInformationRequired"}],id));}
 [Fact] public void ExternalReferralRemainsInAuditButDoesNotOverrideLaterTerminalC4Resolution(){var id=Guid.NewGuid();var f=Findings()[23];var closure=Close(f,id) with{Revision=2};var external=closure with{Operation="HumanReviewRecorded",ReviewOutcome="FurtherInstitutionalLegalReview",Revision=1};Assert.Empty(RegulatoryProgression.Holds([f],[external,closure],id));Assert.Equal("FurtherInstitutionalLegalReview",external.ReviewOutcome);}
}
